import os
import sys

# Ensure modules can be imported
sys.path.append(os.path.abspath(os.path.join(os.path.dirname(__file__), '..')))

# 1. Update imports to use the new exact ID tracking logic
from data_loaders.particle_io import load_streamed_trajectories, extract_hit_list_from_time_capsule
from plotting_core.trajectory_3d import plot_trajectories_with_sensor

def main():
    # --- Configuration ---
    map_dir = r"Z:\map\map_cube_16m_approach.dat"
    
    # 2. Add the path to the Time Capsule generated by Stage 1
    time_capsule_file = r"Z:\Particle_PostProcess_Outputs\20260803_particle_cube_16mapproach\sensor_8x8x8\1200-1800_sensor_density\sensor_hit_ids.txt"
    trajectory_csv = r"Z:\Particle_PostProcess_Outputs\20260803_particle_cube_16mapproach\sensor_8x8x8\1200-1800_sensor_density\target_trajectories.csv"

    
    # IMPORTANT: Set this to your actual LBM grid resolution (usually 2.0m)
    dx = 2.0 
    
    # Time step range
    start_step = 1200
    end_step = 1800  
    
    # Sensor Parameters - PASSED IN PHYSICAL METERS
    sensor_center = (3672, 64, 90) 
    sensor_size = (8, 8, 8) 
    
    # 3. Target Sensor ID (Assuming 0 is the index of the first sensor in your C++ list)
    target_sensor_id = 1 
    
    # Dynamic output path generation
    sensor_folder = f"sensor_{sensor_size[0]}x{sensor_size[1]}x{sensor_size[2]}"
    loc_folder = f"loc_{sensor_center[0]}_{sensor_center[1]}_{sensor_center[2]}"
    
    # 4. Update the filename to reflect that this is a True Pathway plot
    output_path = os.path.join(
        "../figures", "20260803_particle_cube_16mapproach_trajectories", sensor_folder, loc_folder,
        f"true_pathways_sensor_{target_sensor_id}_steps_{start_step}-{end_step}.png"
    )
    
    # --- Execution ---
    print(f"Reading Time Capsule for Sensor ID {target_sensor_id}...")
    
    # 5. Extract the successful IDs first
    target_particle_ids = extract_hit_list_from_time_capsule(time_capsule_file, target_sensor_id)
    
    if not target_particle_ids:
        print(f"[ERROR] No particles hit Sensor {target_sensor_id} in the Time Capsule!")
        return
        
    print(f"Found {len(target_particle_ids)} unique successful particles. Loading binary trajectories from steps {start_step} to {end_step}...")
    print(f"Generating True Pathways for Sensor {target_sensor_id}...")

    # 6. Pass the specific target list to the binary reader
    trajectories = load_streamed_trajectories(trajectory_csv, time_capsule_file, target_sensor_id)
    
    # Optional safety filter: Only plot trajectories that actually existed during this specific time window
    active_trajectories = {p_id: path for p_id, path in trajectories.items() if len(path) > 0}
    
    print(f"Successfully tracked {len(active_trajectories)} unique particles through this time window.")
    
    print("Rendering 3D scene with PyVista...")
    # NOTE: Ensure plot_trajectories_with_sensor only multiplies particle coordinates by dx, 
    # and leaves the sensor_center/sensor_size alone since they are already in meters!
    plot_trajectories_with_sensor(active_trajectories, sensor_center, sensor_size, output_path, map_dir, dx)

if __name__ == "__main__":
    main()